// Display preferences are independent of the run and survive character changes.
const DISPLAY_DEFAULTS={text:100,ui:100,zoom:100};
function normalizeDisplay(value={}){const out={};for(const key of ['text','ui','zoom']){const n=Number(value[key]);out[key]=Number.isFinite(n)?Math.max(key==='zoom'?50:80,Math.min(key==='zoom'?150:140,n)):100;}return out;}
let displayPrefs;try{displayPrefs=normalizeDisplay(JSON.parse(localStorage.getItem('ashbound-display'))||{});}catch{displayPrefs={...DISPLAY_DEFAULTS};}
function applyDisplay(){if(globalThis.ASHBOUND_HEADLESS||!document.documentElement?.style?.setProperty)return;document.documentElement.style.setProperty('--text-scale',displayPrefs.text/100);document.documentElement.style.setProperty('--game-scale',displayPrefs.ui*displayPrefs.zoom/10000);}
function updateDisplay(key,value){if(!['text','ui','zoom'].includes(key))return;displayPrefs=normalizeDisplay({...displayPrefs,[key]:value});applyDisplay();try{localStorage.setItem('ashbound-display',JSON.stringify(displayPrefs));}catch{}const output=document.getElementById('display-'+key);if(output)output.textContent=displayPrefs[key]+'%';}
function resetDisplay(){for(const key of ['text','ui','zoom'])updateDisplay(key,100);document.querySelectorAll('#display-dialog input').forEach(el=>el.value=100);}
function openDisplaySettings(){if(document.getElementById('display-dialog'))return;const dialog=document.createElement('dialog');dialog.id='display-dialog';dialog.innerHTML=`<form method="dialog"><div class="display-heading"><h2>表示設定</h2><button aria-label="表示設定を閉じる">閉じる</button></div><p>画面幅に合わせてレイアウトを自動調整します。設定はこのブラウザに保存されます。</p>${[['text','文字サイズ',80,140],['ui','UIサイズ',80,140],['zoom','画面倍率',50,150]].map(([key,label,min,max])=>`<label>${label} <output id="display-${key}">${displayPrefs[key]}%</output><input aria-label="${label}" type="range" min="${min}" max="${max}" step="5" value="${displayPrefs[key]}" oninput="updateDisplay('${key}',this.value)"></label>`).join('')}<p>スマートフォンでは2本指のピンチ操作でも拡大・縮小できます。</p><button type="button" onclick="resetDisplay()">標準に戻す</button>${cloudSaveControls()}${saveBackupControls()}</form>`;document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();document.getElementById('display-settings')?.focus();});dialog.showModal();}
// Capture each actual HP loss at the primitive damage boundary, including nested laceration ticks.
let damageDisplayTime=0;
function recordDamageEvent(unit,amount,kind='',channel='hp'){if(globalThis.ASHBOUND_HEADLESS||amount<=0)return;const r=S.run,key=unit===r?'player':r?.enemies?.indexOf(unit);if(key==null||key===-1)return;const el=document.querySelector(`[data-entity="${key}"]`);if(!el)return;const rect=el.getBoundingClientRect(),now=Date.now(),start=Math.max(now,damageDisplayTime);damageDisplayTime=start+140;const x=rect.left+rect.width/2,y=rect.top+Math.min(80,rect.height/2);setTimeout(()=>{const label=document.createElement('b');label.className='damage-float damage-event'+(channel==='block'?' block-damage':'');label.textContent=(kind?kind+' ':'')+amount;label.style.left=x+'px';label.style.top=y+'px';document.body.append(label);setTimeout(()=>label.remove(),1100);},start-now);}
if(!globalThis.ASHBOUND_HEADLESS&&document.documentElement?.style?.setProperty){applyDisplay();const button=document.createElement('button');button.id='display-settings';button.textContent='表示設定';button.onclick=openDisplaySettings;document.body.append(button);}
